# Generated by Rosetta: R6 classes for the r_demo native library.
# Load the shared library with dyn.load() before sourcing; the result is a list of exports.
`r_demo` <- local({
if (!requireNamespace("R6", quietly = TRUE)) stop("Install the R6 package")
.rosetta_dll <- getLoadedDLLs()[["r_demo"]]
if (is.null(.rosetta_dll)) stop("Load the r_demo shared library with dyn.load() first")
.rosetta_routines <- getDLLRegisteredRoutines(.rosetta_dll)$.Call
for (.rosetta_name in names(.rosetta_routines)) assign(.rosetta_name, .rosetta_routines[[.rosetta_name]])
.rosetta_object <- R6::R6Class("RosettaObject", cloneable = FALSE, public = list(
  .ptr = NULL,
  close = function() { .Call(`.rs_release`, self); invisible(NULL) },
  print = function(...) { cat("<", class(self)[[1L]], ">\n", sep = ""); invisible(self) }
))
.rosetta_ops <- function(e1, e2) {
  unary <- missing(e2)
  name <- switch(.Generic, "+" = if (unary) "__pos__" else "__add__", "-" = if (unary) "__neg__" else "__sub__",
    "*" = "__mul__", "/" = "__truediv__", "%%" = "__mod__", "==" = "__eq__", "!=" = "__ne__", "<" = "__lt__",
    "<=" = "__le__", ">" = "__gt__", ">=" = "__ge__", "&" = "__and__", "|" = "__or__", "!" = "__not__", NULL)
  method <- if (!is.null(name) && inherits(e1, "RosettaObject")) e1[[name]] else NULL
  if (!is.function(method)) {
    if (.Generic %in% c("==", "!=") && !unary && inherits(e1, "RosettaObject") && inherits(e2, "RosettaObject"))
      return((.Generic == "==") == identical(e1, e2))
    stop("operator ", .Generic, " is not defined for ", class(e1)[[1L]])
  }
  if (unary) method() else method(e2)
}
.rosetta_callable <- function(ptr) { force(ptr); function(...) .Call(`.rs_invoke`, ptr, list(...)) }
`r_demo__add` <- function(...) .Call(`.rs_0`, NULL, list(...))
`r_demo__negate` <- function(...) .Call(`.rs_1`, NULL, list(...))
`r_demo__half` <- function(...) .Call(`.rs_2`, NULL, list(...))
`r_demo__greet` <- function(...) .Call(`.rs_3`, NULL, list(...))
`r_demo__too_large` <- function(...) .Call(`.rs_4`, NULL, list(...))
`r_demo__fail` <- function(...) .Call(`.rs_5`, NULL, list(...))
`r_demo__live` <- function(...) .Call(`.rs_6`, NULL, list(...))
