  public = list(
    initialize = function(...) {
      if (...length() == 1L && inherits(..1, "rosetta_ptr")) self$.ptr <- ..1
      else { if (!is.null(self$.ptr)) stop("native object already initialized"); self$.ptr <- .Call(`.rs_17`, list(...)) }
      invisible(self)
    },
    `add` = function(...) .Call(`.rs_7`, self, list(...)),
    `value` = function(...) .Call(`.rs_8`, self, list(...)),
