    `initial` = function(value) if (missing(value)) .Call(`.rs_13`, self) else invisible(.Call(`.rs_14`, self, value)),
    `label` = function(value) if (missing(value)) .Call(`.rs_15`, self) else invisible(.Call(`.rs_16`, self, value))
