`r_demo__Counter`$`answer` <- function(...) .Call(`.rs_9`, NULL, list(...))
`r_demo__Counter`$`live` <- function(...) .Call(`.rs_10`, NULL, list(...))
.rosetta_onload <- function(env = parent.frame()) {
  values <- .Call(`.rs_init`, env)
  owners <- attr(values, "owners")
  for (i in seq_along(values)) {
    if (nzchar(owners[[i]])) assign(names(values)[[i]], values[[i]], envir = get(owners[[i]], envir = env))
    else assign(names(values)[[i]], values[[i]], envir = env)
  }
  registerS3method("Ops", "RosettaObject", .rosetta_ops, envir = env)
  invisible(NULL)
}
.rosetta_exports <- c("r_demo__Counter", "r_demo__add", "r_demo__fail", "r_demo__greet", "r_demo__half", "r_demo__live", "r_demo__negate", "r_demo__too_large")
.rosetta_onload(environment())
mget(.rosetta_exports, envir = environment())
})
